query GetTeamMemberRunProjection($teamRunId: String!, $agentRunId: String!) {
  getTeamMemberRunProjection(teamRunId: $teamRunId, agentRunId: $agentRunId) {
    agentRunId
    summary
    lastActivityAt
    conversation
    activities
    hasEarlierActiveTraceEvents
    __typename
  }
}
